def main():
    import sys
    n, m, c0, d0 = map(int, sys.stdin.readline().split())
    stuffings = []
    for _ in range(m):
        a, b, c, d = map(int, sys.stdin.readline().split())
        max_count = a // b
        stuffings.append((c, d, max_count))

    # Initialize DP array
    dp = [0] * (n + 1)

    # First, handle the no-stuffing option as an unbounded knapsack
    for i in range(c0, n + 1):
        if dp[i - c0] + d0 > dp[i]:
            dp[i] = dp[i - c0] + d0

    # Then process each stuffing type as a 0-1 knapsack (each can be used up to max_count times)
    for c, d, max_count in stuffings:
        # We need to process in reverse to avoid using the same item multiple times in the same step
        for i in range(n, c - 1, -1):
            # Check all possible counts of this stuffing
            for k in range(1, max_count + 1):
                if i >= k * c:
                    if dp[i - k * c] + k * d > dp[i]:
                        dp[i] = dp[i - k * c] + k * d
                else:
                    break

    print(dp[n])

if __name__ == "__main__":
    main()
